-- Dữ liệu mẫu cho LocalDemoApplication (H2 trong bộ nhớ, chỉ chạy trên máy). Không chứa mật khẩu:
-- cột password là chỗ giữ, LocalDemoApplication đặt mật khẩu từ biến môi trường UTE_DEMO_PASSWORD khi khởi động.
ALTER TABLE shipment_order ALTER COLUMN revision SET DEFAULT 0;
-- ===== Shipper có dữ liệu thống kê nhiều ngày (chỉ bản H2 xem thử, không phải Aiven) =====
-- thongke1: 120 đơn trong 30 ngày (4 đơn/ngày), phần lớn thành công
SELECT 500 + X, 'UTE-TK1-' || X, 2, 6, 'Shop Hoa Mai', '1 Võ Văn Ngân, Linh Chiểu, Thủ Đức, TP.HCM', CASE MOD(X, 8) WHEN 0 THEN 'Nguyễn Văn An' WHEN 1 THEN 'Trần Quốc Bình' WHEN 2 THEN 'Lê Hoàng Phúc' WHEN 3 THEN 'Phạm Đức Duy' WHEN 4 THEN 'Hoàng Minh Quân' WHEN 5 THEN 'Huỳnh Tấn Phát' WHEN 6 THEN 'Võ Thành Đạt' ELSE 'Đặng Quốc Việt' END, '09110' || LPAD(X, 5, '0'), (10 + MOD(X, 90)) || ' Lê Văn Việt, Hiệp Phú, Thủ Đức, TP.HCM',
       1 + MOD(X, 5), CASE MOD(X, 3) WHEN 0 THEN 'EXPRESS' ELSE 'STANDARD' END, 15000 + MOD(X, 7) * 5000,
       CASE WHEN MOD(X, 25) = 0 THEN 'RETURNED' WHEN MOD(X, 10) = 0 THEN 'FAILED' ELSE 'DELIVERED' END,
       DATEADD('HOUR', -(((X - 1) / 4) * 24 + MOD(X, 4) * 2 + 6), CURRENT_TIMESTAMP), DATEADD('HOUR', -(((X - 1) / 4) * 24 + MOD(X, 4) * 2 + 1), CURRENT_TIMESTAMP)
FROM SYSTEM_RANGE(1, 120);
-- thongke2: 60 đơn trong 30 ngày (2 đơn/ngày), nhiều lượt thất bại / hoàn trả
SELECT 620 + X, 'UTE-TK2-' || X, 2, 7, 'Tiệm Sách Cũ', '220 Kha Vạn Cân, Hiệp Bình Chánh, Thủ Đức, TP.HCM', CASE MOD(X, 6) WHEN 0 THEN 'Ngô Đình Khang' WHEN 1 THEN 'Dương Minh Trí' WHEN 2 THEN 'Lâm Gia Bảo' WHEN 3 THEN 'Tô Hữu Nghĩa' WHEN 4 THEN 'Trương Văn Lực' ELSE 'Mai Xuân Trường' END, '09120' || LPAD(X, 5, '0'), (5 + MOD(X, 60)) || ' Đặng Văn Bi, Bình Thọ, Thủ Đức, TP.HCM',
       1 + MOD(X, 3), CASE MOD(X, 5) WHEN 0 THEN 'SUPER_EXPRESS' ELSE 'STANDARD' END, 20000 + MOD(X, 5) * 8000,
       CASE WHEN MOD(X, 9) = 0 THEN 'RETURNED' WHEN MOD(X, 4) = 0 THEN 'FAILED' ELSE 'DELIVERED' END,
       DATEADD('HOUR', -(((X - 1) / 2) * 24 + MOD(X, 2) * 3 + 6), CURRENT_TIMESTAMP), DATEADD('HOUR', -(((X - 1) / 2) * 24 + MOD(X, 2) * 3 + 2), CURRENT_TIMESTAMP)
FROM SYSTEM_RANGE(1, 60);
-- thongke3: 30 đơn rải trong 90 ngày (3 ngày một đơn) -> xem kỳ dài, nhiều ngày trống
SELECT 680 + X, 'UTE-TK3-' || X, 2, 8, 'Cửa hàng Điện Tử 3A', '15 Hoàng Diệu 2, Linh Trung, Thủ Đức, TP.HCM', CASE MOD(X, 5) WHEN 0 THEN 'Kiều Anh Tú' WHEN 1 THEN 'Lục Văn Thắng' WHEN 2 THEN 'Quách Minh Hiếu' WHEN 3 THEN 'Châu Đức Lộc' ELSE 'Từ Quang Khải' END, '09130' || LPAD(X, 5, '0'), (1 + MOD(X, 40)) || ' Tô Vĩnh Diện, Linh Chiểu, Thủ Đức, TP.HCM',
       2, 'STANDARD', 30000 + MOD(X, 4) * 10000,
       CASE WHEN MOD(X, 6) = 0 THEN 'FAILED' ELSE 'DELIVERED' END,
       DATEADD('HOUR', -((X - 1) * 72 + 8), CURRENT_TIMESTAMP), DATEADD('HOUR', -((X - 1) * 72 + 3), CURRENT_TIMESTAMP)
FROM SYSTEM_RANGE(1, 30);
-- Nhật ký chuyển trạng thái (thống kê đếm theo nhật ký) và thanh toán COD (biểu đồ dòng tiền theo ngày thu)
SELECT o.id, o.shipper_id, u.full_name, CASE WHEN o.status = 'RETURNED' THEN 'FAILED' ELSE 'IN_TRANSIT' END, o.status,
       CASE WHEN o.status = 'FAILED' THEN 'CUSTOMER_ABSENT' ELSE NULL END, '', NULL, o.updated_at
FROM shipment_order o JOIN app_user u ON u.id = o.shipper_id WHERE o.shipper_id IN (6, 7, 8);
SELECT o.id, 'COD', CASE WHEN o.status = 'DELIVERED' THEN 'PAID' ELSE 'UNPAID' END, o.shipping_fee, 0,
       CASE WHEN o.status = 'DELIVERED' THEN o.updated_at ELSE NULL END, o.created_at, o.updated_at
FROM shipment_order o WHERE o.shipper_id IN (6, 7, 8);
ALTER TABLE app_user ALTER COLUMN id RESTART WITH 100;
ALTER TABLE shipment_order ALTER COLUMN id RESTART WITH 1000;
